import assert from 'node:assert/strict';
import { Session } from './src/session.js';

let calls = 0;
const paused = new Session({ queryFn({ signal }) { calls++; assert.equal(signal.aborted, false); return Promise.resolve('stop'); }, timers: { schedule(fn) { fn(); } } }, { online: false });
const handle = paused.subscribe('central');
assert.equal(paused.snapshot('central').fetchStatus, 'paused');
paused.unsubscribe(handle);
assert.equal(paused.snapshot('central').fetchStatus, 'idle');
paused.online(true);
await Promise.resolve();
assert.equal(calls, 0);

let resolve;
const running = new Session({ queryFn() { return new Promise(r => { resolve = r; }); }, timers: { schedule() {} } });
const active = running.subscribe('central');
running.unsubscribe(active);
resolve('cached');
await Promise.resolve();
assert.deepEqual(running.snapshot('central'), { status: 'success', fetchStatus: 'idle', data: 'cached' });

let aborted = false;
const consuming = new Session({ queryFn({ signal }) { signal.addEventListener('abort', () => { aborted = true; }); return new Promise(() => {}); }, timers: { schedule() {} } });
const consumed = consuming.subscribe('central');
consuming.unsubscribe(consumed);
assert.equal(aborted, true);
assert.deepEqual(consuming.snapshot('central'), { status: 'pending', fetchStatus: 'idle', data: null });
EOF"

